import React from 'react';
const rarities=[['Mil-Spec','Bleu','Les drops les plus accessibles.'],['Restricted','Violet','Plus rares et plus chers.'],['Classified','Rose','Une vraie montée en gamme.'],['Covert','Rouge','Les skins très rares.'],['Contraband','Or','Catégorie exceptionnelle.'],['Extraordinary','Or spécial','Gants et récompenses ultra rares.']];
const GuidePage=()=> <div className="container guide-page"><section className="guide-hero"><span className="section-kicker">WELLCASE / FIELD GUIDE</span><h1>Comprendre les <em>drops.</em></h1><p>Tout ce qu’il faut savoir pour construire le meilleur inventaire et gagner ton duel 48H.</p></section><section className="guide-section"><div className="guide-section-title"><span>01</span><div><span className="section-kicker">RARETÉS</span><h2>L'ordre des raretés</h2></div></div><div className="rarity-list">{rarities.map((r,i)=><article key={r[0]} className={`rarity-row rarity-${r[0].toLowerCase()}`}><strong>0{i+1}</strong><div className="rarity-dot"/><div><h3>{r[0]}</h3><p>{r[2]}</p></div><span>{r[1]}</span></article>)}</div></section><section className="guide-cards"><article><span>02</span><h3>Comment gagner</h3><p>Ouvre des caisses, fais des upgrades et garde les meilleurs skins. La valeur virtuelle de ton inventaire et ton cash forment ton score.</p></article><article><span>03</span><h3>Probabilités</h3><p>Chaque caisse possède son propre pool. Le serveur choisit le drop, puis la roulette révèle ce résultat.</p></article><article><span>04</span><h3>Float & valeur</h3><p>Le float est une donnée de collection simulée. La valeur sert aux ventes, upgrades et classements.</p></article><article><span>05</span><h3>XP & Pass</h3><p>Les ouvertures, upgrades, bonus quotidiens et quêtes donnent de l'XP. Les niveaux débloquent des bonus ×3 et ×5.</p></article></section></div>;
export default GuidePage;
